import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

export function migratePanelConfig(env, override) {
  if (!override || !override.includes('nginx-ssl.conf') || !/^    ports:/m.test(override)) {
    return { env, override, changed: false };
  }
  // Only migrate the exact override generated by the old installer.
  const generated = /^(?:version: "3\.8"\r?\n\r?\n)?services:\r?\n  frontend:\r?\n    ports:\r?\n      - "([0-9]+):443"\r?\n    volumes:\r?\n      - \.\/nginx-ssl\.conf:\/etc\/nginx\/conf\.d\/default\.conf:ro\r?\n      - [^\r\n]+:\/etc\/ssl\/certs\/fullchain\.pem:ro\r?\n      - [^\r\n]+:\/etc\/ssl\/private\/privkey\.pem:ro\r?\n?$/;
  const match = override.match(generated);
  if (!match) throw new Error('Обнаружена нестандартная SSL-конфигурация. Перенесите внешний порт в PORT, задайте FRONTEND_PORT=443 и уберите ports из SSL override вручную.');
  const port = Number(match[1]);
  if (port < 1 || port > 65535) throw new Error('Некорректный внешний SSL-порт в override.');
  if ((env.match(/^PORT=/gm) || []).length !== 1 || (env.match(/^FRONTEND_PORT=/gm) || []).length > 1) {
    throw new Error('Не удалось однозначно определить настройки портов в .env.');
  }
  const newline = env.includes('\r\n') ? '\r\n' : '\n';
  let nextEnv = env.replace(/^PORT=[^\r\n]*/m, `PORT=${port}`);
  nextEnv = /^FRONTEND_PORT=/m.test(nextEnv)
    ? nextEnv.replace(/^FRONTEND_PORT=[^\r\n]*/m, 'FRONTEND_PORT=443')
    : `${nextEnv}${nextEnv.endsWith('\n') ? '' : newline}FRONTEND_PORT=443${newline}`;
  return {
    env: nextEnv,
    override: override.replace(/^    ports:\r?\n      - "[0-9]+:443"\r?\n/m, ''),
    changed: true,
  };
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  try {
    const envPath = resolve('.env');
    const overridePath = resolve('docker-compose.override.yml');
    const result = migratePanelConfig(readFileSync(envPath, 'utf8'), existsSync(overridePath) ? readFileSync(overridePath, 'utf8') : undefined);
    if (result.changed) {
      // Write the port settings first; a retry can safely finish removing old ports.
      writeFileSync(envPath, result.env);
      writeFileSync(overridePath, result.override);
      console.log('SSL-конфигурация обновлена, внешний порт и сертификаты сохранены.');
    }
  } catch (error) {
    console.error(error.message);
    process.exitCode = 1;
  }
}
